extern "C" {

/// @brief Read power management hcode error log entries (metadata only)
///
/// @param[in]  i_target        Reference to proc chip target
/// @param[in]  i_ppe_type      PPE_TYPE_GPE, PPE_TYPE_QME, PPE_TYPE_MAX
/// @param[in]  i_ppe_instance  Instance number of the PPE type in i_ppe_type
///                             For PPE_TYPE_GPE, Instance 0-1: Not Applicable
///                             For PPE_TYPE_GPE, Instance 2: PGPE 3: XGPE
///                             For PPE_TYPE_QME, Instances 0 to 7
///                             For PPE_TYPE_MAX, Instance is ignored
/// @param[out] o_elog_tbl      Pointer to error log table data storage
/// @param[in]  i_local         Debug only, defaulted to 'false'
///                             false: read error entries from global table
///                             true: read error entries from local PPE table
///
/// @return FAPI_RC_SUCCESS if success, else error code
/// @note PPE_TYPE_MAX will attempt to get error logs entries across all engines
///
    fapi2::ReturnCode p10_pm_elog_list (
        const fapi2::Target<fapi2::TARGET_TYPE_PROC_CHIP>& i_target,
        const enum PPE_TYPES i_ppe_type,
        const uint32_t i_ppe_instance,
        hcode_error_table_t* o_elog_tbl,
        const bool i_local = false );


/// @brief Read an error log
///
/// @param[in]  i_target        Reference to proc chip target
/// @param[in]  i_elog_entry    Elog entry indicating which error
///                             log to read
/// @param[out] o_data          Pointer to pre-allocated error log data storage
/// @param[in]  i_offset        Offset (bytes) in the error log to read from
/// @param[in]  i_len           Length (bytes) of error log data to read
/// @param[in]  i_local         Debug only, defaulted to 'false'
///                             false: read error logs from global table
///                             true: read error logs from local PPE table
///
/// @return FAPI_RC_SUCCESS if success, else error code
/// @note Callers without memory constraints can call this once (skip passing
///       the optional i_offset, i_len inputs) to read full error log)
/// @note Memory constrained callers may call this in a loop with i_offset,
///       i_len and o_data incremented properly, until full error log with len
///       of i_elog_entry->elog_len) is streamed out
///
    fapi2::ReturnCode p10_pm_elog_read (
        const fapi2::Target<fapi2::TARGET_TYPE_PROC_CHIP>& i_target,
        const uint64_t i_elog_entry,
        uint8_t* o_data,
        const uint32_t i_offset = 0,
        const uint32_t i_len = 0,
        const bool i_local = false);


/// @brief Purge / delete an error log entry
///
/// @param[in]  i_target        Reference to proc chip target
/// @param[in]  i_elog_entry    Elog entry indicating which error
///                             log to purge
/// @param[in]  i_local         Debug only, defaulted to 'false'
///                             false: read error logs from global table
///                             true: read error logs from local PPE table
///
/// @return FAPI_RC_SUCCESS if success, else error code
///
    fapi2::ReturnCode p10_pm_elog_purge (
        const fapi2::Target<fapi2::TARGET_TYPE_PROC_CHIP>& i_target,
        const uint64_t i_elog_entry,
        const bool i_local = false );


/// @brief Dissects error log binary to extract key constituents
///
/// @param[in]  i_elogBuf           error log binary
/// @param[in]  o_elogDissectionSum struct containing info pertaining to its origin
///
/// @return FAPI_RC_SUCCESS if success, else error code
///
    fapi2::ReturnCode p10_pm_elog_dissect( uint8_t* i_elogBuf, ElogDissectionSum& o_elogDissectionSum );
} // extern "C"

#endif // _P10_PM_ELOG_H_
